<div class="flex min-h-screen"><div class="hidden md:block"><?php require __DIR__ . '/../partials/staff-sidebar.php'; ?></div><div class="min-w-0 flex-1"><main class="mx-auto max-w-6xl px-5 py-8 sm:px-8 sm:py-10"><div><p class="font-mono-ui text-[10px] uppercase tracking-[.18em] text-teal">Comunicação clínica</p><h1 class="mt-2 text-3xl font-bold tracking-[-.04em]">Mensagens</h1><p class="mt-2 text-sm text-slate-500">Responda aos pacientes e mantenha o acompanhamento documentado.</p></div><section class="mt-8 overflow-hidden rounded-2xl border border-[#e1d8ca] bg-white"><?php if (!$messages): ?><p class="px-5 py-12 text-center text-sm text-slate-500">Não existem mensagens.</p><?php else: ?><?php foreach ($messages as $message): ?><div class="border-b border-[#eee7dc] px-5 py-5 last:border-0"><div class="flex flex-col justify-between gap-2 sm:flex-row sm:items-start"><div><a href="<?= url('patient', ['id' => $message['patient_id']]) ?>" class="text-sm font-bold hover:text-teal"><?= e($message['patient_name']) ?></a><p class="mt-1 text-xs text-slate-500"><?= e($message['medical_record_number']) ?> · <?= e((new DateTimeImmutable($message['created_at']))->format('d/m/Y H:i')) ?></p></div><span class="rounded-full <?= $message['sender_role'] === 'patient' ? 'bg-[#fff0dc] text-[#a85f2f]' : 'bg-[#e8f0e8] text-teal' ?> px-3 py-1 text-[10px] font-bold"><?= e(role_label((string) $message['sender_role'])) ?></span></div><p class="mt-4 rounded-xl bg-[#fbf8f1] px-4 py-3 text-sm leading-6"><?= nl2br(e($message['body'])) ?></p><form method="post" class="mt-3 flex flex-col gap-2 sm:flex-row"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="reply-message"><input type="hidden" name="patient_id" value="<?= (int) $message['patient_id'] ?>"><input name="body" required maxlength="2000" placeholder="Responder a este paciente..." class="min-w-0 flex-1 rounded-lg border border-[#d7cebf] bg-[#fffdf8] px-3 py-3 text-sm outline-none focus:border-teal"><button class="rounded-lg bg-teal px-4 py-3 text-sm font-bold text-white">Responder</button></form></div><?php endforeach; ?><?php endif; ?></section></main></div></div>